public class LoopGuard {
    private final int maxSteps = 15, maxSameCall = 2;
    private final long deadline = System.currentTimeMillis() + 180_000;   // 总超时 3 分钟
    private final long tokenBudget = 50_000;
    private final Map<String, Integer> calls = new HashMap<>();
    private int steps; private long tokens;

    /** 每次工具调用前检查，返回 null 表示放行，否则返回给模型的错误说明 */
    public String check(String tool, String argsJson, long usedTokens) {
        tokens += usedTokens;
        if (++steps > maxSteps) throw new LoopAbort("超过最大步数");
        if (System.currentTimeMillis() > deadline) throw new LoopAbort("超过总时长");
        if (tokens > tokenBudget) throw new LoopAbort("超过 token 预算");
        String key = tool + ":" + DigestUtils.sha256Hex(argsJson);
        if (calls.merge(key, 1, Integer::sum) > maxSameCall) {
            return "错误：已用相同参数调用过 " + tool + "，结果不会改变，请换一种方法或直接给出结论。";
        }
        return null;
    }
}

