public Object call(ToolReq req, User u) {
  ToolSpec spec = registry.get(req.name());
  auth.assertCanUse(u, spec);
  Object args = schema.validate(req.arguments());   // 类型/枚举/路径
  if (spec.destructive()) {
    approval.require(u, spec, args);               // 人工确认
  }
  try (var scope = sandbox.open(u, spec)) {
    return timed(spec.timeout(), () -> scope.invoke(args));
  } finally {
    audit.log(u, spec, args);
  }
}
